INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=21176&keyref=6007623', '3A2042', now(), 'Official source captured 2026-09-11. Direct purchase THB 11,883,000, 60 sq.wah, three connected units, source counts 8 bedrooms/2 bathrooms. Registered four storeys versus surveyed three plus mezzanine and roof addition. Front covered extension encroaches road; private road has registered easement according to SAM. Both disclosures retained. Coordinates extracted from navigation href and independently matched to show_map.php parameters, without administrator-provided coordinates. 36 original images retained. All-status duplicate search found no matches; shared keyref not used as identity.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 3 Connected Shophouses, Na Pa, Chon Buri, THB 11.883M', 'Three adjoining internally connected shophouses at 88/24–26, Na Pa, Mueang Chon Buri, Chon Buri. Three plots, deeds 167704, 167705 and 167722, total 60 sq.wah (240 sq.m.). SAM announced price THB 11,883,000; asset 3A2042. The page reports eight bedrooms and two bathrooms for the listing.
